/**
 * Nxeon / Cyrus separation report. Reads the working tree and prints the coupling table (dimension | state | evidence |
 * what "separate" means | effort) so the numbers never go stale. Pure fs, no dependencies.
 *
 *   npx tsx scripts/cyrus/separation-report.ts            markdown report
 *   npx tsx scripts/cyrus/separation-report.ts --json     machine-readable (same facts)
 *   npx tsx scripts/cyrus/separation-report.ts --lists    also print every forward / reverse import edge
 *
 * Ownership model (path based, see ownerOf):
 *   cyrus    lib/cyrus/**, lib/modbuilder/**, lib/cyrus-mods/**, lib/actions-cyrus-*.ts, app and components paths that
 *            have a "cyrus" / "mod-builder" / "modbuilder" segment (or Cyrus*.tsx file name), worker/cyrus-*.ts
 *   bridge   lib/cyrus/host/nxeon.ts (the one sanctioned Cyrus -> Nxeon adapter)
 *   contract lib/cyrus-client, lib/cyrus-bridge, lib/nxeon-platform (versioned cross-app contract, owned by neither)
 *   nxeon    everything else
 * Forward edge = cyrus file imports nxeon file. Reverse edge = nxeon file imports cyrus file.
 * The same scanner backs test/cyrus-reverse-imports.test.ts (ratchet).
 */
import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import path from "node:path";

export const ROOT = path.resolve(__dirname, "..", "..");
const SCAN_DIRS = ["app", "components", "lib", "worker"];
const SCAN_FILES = ["middleware.ts", "instrumentation.ts"];
const IMPORT_RE = /(?:\bfrom|\bimport|\brequire)\s*\(?\s*["']([^"']+)["']/g;

export type Owner = "cyrus" | "bridge" | "contract" | "nxeon";
export type CyrusLayer = "lib/cyrus" | "lib/modbuilder" | "lib/cyrus-mods" | "lib/actions-cyrus" | "app" | "components" | "worker";

export function ownerOf(rel: string): Owner {
  if (rel === "lib/cyrus/host/nxeon") return "bridge";
  if (rel === "lib/cyrus/host/nxeon.ts") return "bridge";
  if (/^lib\/(cyrus-client|cyrus-bridge|nxeon-platform)(\/|$)/.test(rel)) return "contract";
  if (/^lib\/(cyrus|modbuilder|cyrus-mods)(\/|$)/.test(rel)) return "cyrus";
  if (/^lib\/actions-cyrus-/.test(rel)) return "cyrus";
  if (/^worker\/cyrus-/.test(rel)) return "cyrus";
  if (/^(app|components)\//.test(rel)) {
    const segs = rel.split("/");
    if (segs.some((s) => /cyrus|mod-?builder/i.test(s.replace(/\.(tsx?|css)$/, "")))) return "cyrus";
  }
  return "nxeon";
}

export function layerOf(rel: string): CyrusLayer {
  if (/^lib\/cyrus(\/|$)/.test(rel)) return "lib/cyrus";
  if (/^lib\/modbuilder(\/|$)/.test(rel)) return "lib/modbuilder";
  if (/^lib\/cyrus-mods(\/|$)/.test(rel)) return "lib/cyrus-mods";
  if (/^lib\/actions-cyrus-/.test(rel)) return "lib/actions-cyrus";
  if (/^worker\//.test(rel)) return "worker";
  if (/^components\//.test(rel)) return "components";
  return "app";
}

function walk(dir: string, out: string[] = []): string[] {
  if (!existsSync(dir)) return out;
  for (const n of readdirSync(dir)) {
    if (n === "node_modules" || n === ".next") continue;
    const p = path.join(dir, n);
    const st = statSync(p);
    if (st.isDirectory()) walk(p, out);
    else if (/\.(ts|tsx)$/.test(n) && !/\.d\.ts$/.test(n)) out.push(p);
