// PROTOTYPE (feature/cyrus-split-design, not wired anywhere): the account-linking decision table of the Cyrus split
// identity model (agent-notes DA-cyrus-split-architecture-2026-10-15.md, section A). PURE: no I/O, no Nxeon imports.
//
// Model: Cyrus has its OWN accounts (CyrusAccount) with FEDERATED identities (CyrusIdentity: provider + subject).
//   provider "nxeon"    = Sign in with Nxeon (Nxeon is an OIDC identity provider; subject = the Nxeon user id)
//   provider "google"   = Continue with Google on cyrus.my (Cyrus' own Google client; subject = Google `sub`)
//   provider "password" = email + password on cyrus.my (subject = the account id; email must be verified to build/pay)
// A Cyrus account is created JUST IN TIME the first time someone signs in to Cyrus (never at Nxeon sign-up), and an
// identity is linked to at most one account (unique provider + subject). Migrated accounts keep id = Nxeon user id.
//
// Hard rules (each has a test in test/cyrus-identity-link-rules.test.ts):
//   R1 an identity that is already linked signs in to ITS account, nothing else (never re-pointed silently)
//   R2 an email match NEVER links or signs in by itself: the person must prove the existing account first
//   R3 an unverified (or only grandfathered) email is never used for matching and never creates an account that can build
//   R4 a signed-in person may add an identity only if that identity is not linked to another account
//   R5 the last sign-in method can never be unlinked; a Nxeon link that funds a bundle cannot be unlinked while active
//   R6 suspended / deleted / erasing accounts never get a session; staff identities never sign in to the customer app
//   R7 upstream deletion of the only identity starts a recovery grace, then erasure; otherwise it just unlinks

export type Provider = "nxeon" | "google" | "password";
export type AccountStatus = "active" | "suspended" | "pending_erasure" | "deleted";

export type Identity = { provider: Provider; subject: string };
export type AccountView = {
  id: string;
  status: AccountStatus;
  /** case-folded primary email, verified or not */
  email: string | null;
  emailVerified: boolean;
  identities: Identity[];
  /** an entitlement paid through Nxeon (bundle / partner grant) is active on this account */
  nxeonFundedEntitlement?: boolean;
};

/** What the identity provider just told us (an OIDC id_token / Google id_token, already signature- and nonce-checked). */
export type Incoming = Identity & {
  email: string | null;
  /** the provider asserts the email is verified */
  emailVerified: boolean;
  /** Nxeon only: the verification is a real one (not the "grandfathered" / fail-open rule of lib/email-verification) */
  emailVerifiedStrong?: boolean;
  /** Nxeon only: the subject is a staff role (ADMIN/SUPPORT/...), which never signs in to the customer app */
  staff?: boolean;
};

export type Lookup = {
  byIdentity(i: Identity): AccountView | null;
  /** active or suspended account whose primary email equals `email` (case-folded) */
  byEmail(email: string): AccountView | null;
};

export type SignInDecision =
  | { kind: "sign_in"; accountId: string }
  | { kind: "create"; email: string | null; emailVerified: boolean; link: Identity }
  | { kind: "link"; accountId: string; link: Identity }
  | { kind: "already_linked"; accountId: string }
  /** an account with this email exists: sign in to it with one of its methods, then the identity is linked (R2) */
  | { kind: "prove_existing"; accountId: string; methods: Provider[]; pendingLink: Identity }
  | { kind: "refuse"; reason: RefuseReason };

export type RefuseReason =
  | "account_suspended" | "account_deleted" | "account_erasing" | "staff"
  | "email_unverified" | "identity_linked_elsewhere" | "malformed";

const fold = (e: string | null | undefined) => (e ?? "").trim().toLowerCase() || null;
const SUBJECT_RE = /^[A-Za-z0-9._:@-]{3,255}$/;

function usableEmail(i: Incoming): boolean {
  if (!i.email || !i.emailVerified) return false;
  if (i.provider === "nxeon") return i.emailVerifiedStrong === true; // R3: Nxeon's grandfathered/fail-open rule is not proof
  return true;
}

function statusRefusal(a: AccountView): RefuseReason | null {
  if (a.status === "suspended") return "account_suspended";
  if (a.status === "deleted") return "account_deleted";
  if (a.status === "pending_erasure") return "account_erasing";
  return null;
}

/**
 * Decide what a successful upstream authentication does.
 * `session` = the Cyrus account already signed in on this browser (a "Connect Nxeon" / "Add Google" flow), or null.
 */
export function decideSignIn(incoming: Incoming, session: AccountView | null, lookup: Lookup): SignInDecision {
  if (!SUBJECT_RE.test(incoming.subject)) return { kind: "refuse", reason: "malformed" };
  if (incoming.staff) return { kind: "refuse", reason: "staff" }; // R6
  const link: Identity = { provider: incoming.provider, subject: incoming.subject };
  const owner = lookup.byIdentity(link);

  // --- a signed-in person adding a method (R4)
  if (session) {
    const bad = statusRefusal(session);
    if (bad) return { kind: "refuse", reason: bad };
    if (owner && owner.id === session.id) return { kind: "already_linked", accountId: session.id };
    if (owner) return { kind: "refuse", reason: "identity_linked_elsewhere" };
    if (session.identities.some((x) => x.provider === incoming.provider && incoming.provider !== "password"))
      // one identity per external provider per account keeps "which Nxeon account is this?" unambiguous
      return { kind: "refuse", reason: "identity_linked_elsewhere" };
    return { kind: "link", accountId: session.id, link };
  }

  // --- R1: a known identity signs in to its own account only
  if (owner) {
    const bad = statusRefusal(owner);
    return bad ? { kind: "refuse", reason: bad } : { kind: "sign_in", accountId: owner.id };
  }

  // --- unknown identity: R3 then R2
  const email = fold(incoming.email);
  if (!usableEmail(incoming)) {
    // Nxeon and Google always send a verified email for a real account; an unverified one is refused (today's bridge rule)
    return { kind: "refuse", reason: "email_unverified" };
  }
  const sameEmail = email ? lookup.byEmail(email) : null;
  if (sameEmail) {
    const bad = statusRefusal(sameEmail);
    if (bad) return { kind: "refuse", reason: bad };
    return { kind: "prove_existing", accountId: sameEmail.id, methods: [...new Set(sameEmail.identities.map((x) => x.provider))], pendingLink: link };
  }
  return { kind: "create", email, emailVerified: true, link };
}

export type UnlinkDecision = { ok: true } | { ok: false; reason: "last_method" | "not_linked" | "funded_by_nxeon" };

/** R5: may `account` remove `which`? */
export function decideUnlink(account: AccountView, which: Identity): UnlinkDecision {
  const has = account.identities.some((x) => x.provider === which.provider && x.subject === which.subject);
  if (!has) return { ok: false, reason: "not_linked" };
  if (account.identities.length <= 1) return { ok: false, reason: "last_method" };
  if (which.provider === "nxeon" && account.nxeonFundedEntitlement) return { ok: false, reason: "funded_by_nxeon" };
  return { ok: true };
}

