// PROTOTYPE tests for the Cyrus split identity model (lib/cyrus/identity/link-rules.ts). Pure, no DB.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { decideSignIn, decideUnlink, onLoginEmail, onUpstreamDeleted, type AccountView, type Incoming, type Lookup } from "../lib/cyrus/identity/link-rules";

const acct = (o: Partial<AccountView> & { id: string }): AccountView => ({ status: "active", email: null, emailVerified: true, identities: [], ...o });
function world(accounts: AccountView[]): Lookup {
  return {
    byIdentity: (i) => accounts.find((a) => a.identities.some((x) => x.provider === i.provider && x.subject === i.subject)) ?? null,
    byEmail: (e) => accounts.find((a) => a.email === e && a.status !== "deleted") ?? null,
  };
}
const nx = (subject: string, email = "a@x.test", o: Partial<Incoming> = {}): Incoming =>
  ({ provider: "nxeon", subject, email, emailVerified: true, emailVerifiedStrong: true, ...o });
const g = (subject: string, email = "a@x.test", o: Partial<Incoming> = {}): Incoming => ({ provider: "google", subject, email, emailVerified: true, ...o });

describe("sign-in decisions", () => {
  it("first Sign in with Nxeon creates a Cyrus account just in time (JIT)", () => {
    const d = decideSignIn(nx("u_nx_1"), null, world([]));
    assert.deepEqual(d, { kind: "create", email: "a@x.test", emailVerified: true, link: { provider: "nxeon", subject: "u_nx_1" } });
  });
  it("R1 a linked identity signs in to its own account", () => {
    const a = acct({ id: "u_nx_1", email: "a@x.test", identities: [{ provider: "nxeon", subject: "u_nx_1" }] });
    assert.deepEqual(decideSignIn(nx("u_nx_1", "changed@x.test"), null, world([a])), { kind: "sign_in", accountId: "u_nx_1" });
  });
  it("R2 same email on both sides never auto-links: prove the existing Cyrus account first", () => {
    const a = acct({ id: "cy_1", email: "a@x.test", identities: [{ provider: "google", subject: "g1" }] });
    const d = decideSignIn(nx("u_nx_9"), null, world([a]));
    assert.equal(d.kind, "prove_existing");
    if (d.kind === "prove_existing") { assert.equal(d.accountId, "cy_1"); assert.deepEqual(d.methods, ["google"]); }
  });
  it("R3 a grandfathered / weak Nxeon verification is not proof of the email", () => {
    assert.deepEqual(decideSignIn(nx("u_nx_2", "a@x.test", { emailVerifiedStrong: false }), null, world([])), { kind: "refuse", reason: "email_unverified" });
    assert.deepEqual(decideSignIn(g("g2", "a@x.test", { emailVerified: false }), null, world([])), { kind: "refuse", reason: "email_unverified" });
  });
  it("R4 connecting Nxeon while signed in links, unless that Nxeon account belongs to someone else", () => {
    const me = acct({ id: "cy_me", email: "me@x.test", identities: [{ provider: "password", subject: "cy_me" }] });
    const other = acct({ id: "cy_other", identities: [{ provider: "nxeon", subject: "u_nx_7" }] });
    assert.deepEqual(decideSignIn(nx("u_nx_5", "different@x.test"), me, world([me, other])), { kind: "link", accountId: "cy_me", link: { provider: "nxeon", subject: "u_nx_5" } });
    assert.deepEqual(decideSignIn(nx("u_nx_7"), me, world([me, other])), { kind: "refuse", reason: "identity_linked_elsewhere" });
  });
  it("R4 one Nxeon account per Cyrus account", () => {
    const me = acct({ id: "cy_me", identities: [{ provider: "nxeon", subject: "u_nx_5" }] });
    assert.deepEqual(decideSignIn(nx("u_nx_6"), me, world([me])), { kind: "refuse", reason: "identity_linked_elsewhere" });
    assert.deepEqual(decideSignIn(nx("u_nx_5"), me, world([me])), { kind: "already_linked", accountId: "cy_me" });
  });
  it("R6 suspended, erasing and staff never get a session", () => {
    const s = acct({ id: "cy_s", status: "suspended", identities: [{ provider: "nxeon", subject: "u_s" }] });
    const e = acct({ id: "cy_e", status: "pending_erasure", identities: [{ provider: "nxeon", subject: "u_e" }] });
    assert.deepEqual(decideSignIn(nx("u_s"), null, world([s])), { kind: "refuse", reason: "account_suspended" });
    assert.deepEqual(decideSignIn(nx("u_e"), null, world([e])), { kind: "refuse", reason: "account_erasing" });
    assert.deepEqual(decideSignIn(nx("u_staff", "s@x.test", { staff: true }), null, world([])), { kind: "refuse", reason: "staff" });
  });
  it("rejects malformed subjects", () => {
    assert.deepEqual(decideSignIn(nx("a b"), null, world([])), { kind: "refuse", reason: "malformed" });
  });
});

describe("unlink, deletion and email change", () => {
  const both = acct({ id: "cy", identities: [{ provider: "nxeon", subject: "u1" }, { provider: "google", subject: "g1" }] });
  it("R5 the last method can never be removed", () => {
    assert.deepEqual(decideUnlink(acct({ id: "x", identities: [{ provider: "nxeon", subject: "u1" }] }), { provider: "nxeon", subject: "u1" }), { ok: false, reason: "last_method" });
    assert.deepEqual(decideUnlink(both, { provider: "nxeon", subject: "u1" }), { ok: true });
    assert.deepEqual(decideUnlink({ ...both, nxeonFundedEntitlement: true }, { provider: "nxeon", subject: "u1" }), { ok: false, reason: "funded_by_nxeon" });
  });
  it("R7 Nxeon account deleted: unlink when another method exists, else recovery grace then erasure", () => {
    assert.deepEqual(onUpstreamDeleted(both, { provider: "nxeon", subject: "u1" }), { action: "unlink", accountId: "cy" });
    const only = acct({ id: "cy2", identities: [{ provider: "nxeon", subject: "u2" }] });
    assert.deepEqual(onUpstreamDeleted(only, { provider: "nxeon", subject: "u2" }), { action: "recovery_grace", accountId: "cy2", graceDays: 30, then: "erase" });
    assert.deepEqual(onUpstreamDeleted(null, { provider: "nxeon", subject: "u3" }), { action: "none" });
  });
  it("email follows Nxeon only when synced and strongly verified", () => {
    const a = acct({ id: "cy", email: "old@x.test", identities: [{ provider: "nxeon", subject: "u1" }] });
    assert.deepEqual(onLoginEmail(a, nx("u1", "New@X.test"), true), { action: "update", to: "new@x.test", notifyOld: true });
    assert.deepEqual(onLoginEmail(a, nx("u1", "new@x.test"), false), { action: "keep" });
    assert.deepEqual(onLoginEmail(a, nx("u1", "new@x.test", { emailVerifiedStrong: false }), true), { action: "keep" });
  });
});

